    /// Generate a [`Fix`] to remove an unnecessary dictionary spread.
    fn unnecessary_spread_fix(
        &self,
        dict_start: TextSize,
        dict_end: TextSize,
        last_end: Option<TextSize>,
    ) -> Option<Fix> {
        let mut tokenizer = SimpleTokenizer::starts_at(self.prev_end, self.source);
        let doublestar = loop {
            if tokenizer.is_bogus() && tokenizer.rest().is_empty() {
                return None;
            }
            let token = tokenizer.next()?;
            if token.kind() == SimpleTokenKind::DoubleStar {
                if &tokenizer.source_text()[token.range()] != "**" {
                    continue;
                }
                if tokenizer.current_offset() > dict_start {
                    return None;
                }
                break token;
            }
            if tokenizer.current_offset() > dict_start {
                return None;
            }
        };

        let mut parentheses = 0;
        let mut tokenizer = SimpleTokenizer::starts_at(doublestar.end(), self.source);
        while tokenizer.current_offset() < dict_start {
            let token = tokenizer.next()?;
            match token.kind() {
                SimpleTokenKind::LParen => parentheses += 1,
                SimpleTokenKind::LBrace if token.start() == dict_start => break,
                kind if kind.is_trivia() => {}
                _ => return None,
            }
        }

        if let Some(last_end) = last_end {
            // Ex) `**{a: 1, b: 2}`
            let mut edits = vec![];
            let mut tokenizer = SimpleTokenizer::starts_at(last_end, self.source);
            let mut closed_dict = false;
            loop {
                if tokenizer.is_bogus() && tokenizer.rest().is_empty() {
                    break;
                }
                let Some(tok) = tokenizer.next() else {
                    break;
                };
                if tok.kind().is_trivia() {
                    continue;
                }
                match tok.kind() {
                    SimpleTokenKind::Comma => {
                        if &tokenizer.source_text()[tok.range()] == "," {
                            edits.push(Edit::range_deletion(tok.range()));
                        }
                    }
                    SimpleTokenKind::RBrace => {
                        if &tokenizer.source_text()[tok.range()] == "}" {
                            edits.push(Edit::range_deletion(tok.range()));
                            if parentheses == 0 {
                                break;
                            }
                            closed_dict = true;
                        }
                    }
                    SimpleTokenKind::RParen if closed_dict => {
                        edits.push(Edit::range_deletion(tok.range()));
                        parentheses -= 1;
                        if parentheses == 0 {
                            break;
                        }
                    }
                    _ if closed_dict => return None,
                    _ => {}
                }
            }
            Some(Fix::safe_edits(
                // Delete the first `**{`
                Edit::deletion(doublestar.start(), dict_start + TextSize::from(1)),
                edits,
            ))
        } else {
            // Ex) `**{}`
            let mut edits = vec![Edit::deletion(doublestar.start(), dict_end)];
            let mut tokenizer = SimpleTokenizer::starts_at(dict_end, self.source);
            while parentheses > 0 {
                let token = tokenizer.next()?;
                if token.kind().is_trivia() {
                    continue;
                }
                if token.kind() != SimpleTokenKind::RParen {
                    return None;
                }
                edits.push(Edit::range_deletion(token.range()));
                parentheses -= 1;
            }
            Some(Fix::safe_edits(edits.remove(0), edits))
        }
    }
